import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    n = int(input_data[0])
    s = input_data[1]
    m = len(s)
    MOD = 1000000007

    if m > 2 * n:
        print(0)
        return

    # Precompute KMP failure function for s
    pi = [0] * m
    k = 0
    for q in range(1, m):
        while k > 0 and s[k] != s[q]:
            k = pi[k - 1]
        if s[k] == s[q]:
            k += 1
        pi[q] = k

    # dp[length][balance][state]
    # length: 0 to 2n
    # balance: 0 to n (number of open minus close brackets, cannot exceed n, cannot be negative)
    # state: current KMP match length for pattern s (0 to m)
    # We only care if we ever reach state m (found s). Once found, we stay in a "found" absorbing state.
    # However, to count sequences containing s, we can sum up all paths that reach state m at any point.
    # Alternatively, make state m an absorbing state and compute total paths to any state >= m at length 2n.
    # Let's use state 0..m. If we reach m, we stay at m.

    max_len = 2 * n
    max_bal = n
    num_states = m + 1  # 0 to m

    # dp[l][b][st]
    dp = [[[0] * num_states for _ in range(max_bal + 1)] for _ in range(max_len + 1)]

    dp[0][0][0] = 1

    for length in range(max_len):
        for balance in range(max_bal + 1):
            for state in range(num_states):
                count = dp[length][balance][state]
                if count == 0:
                    continue

                # Try adding '('
                new_bal = balance + 1
                if new_bal <= max_bal:
                    # Update KMP state
                    if state < m:
                        # Find next state
                        if s[state] == '(':
                            new_state = state + 1
                        else:
                            # mismatch, use KMP logic
                            k = state
                            while k > 0 and s[k] != '(':
                                k = pi[k - 1]
                            if s[k] == '(':
                                k += 1
                            new_state = k
                        # Check if we completed the pattern
                        if new_state == m:
                            new_state = m # absorbing
                    else:
                        new_state = m

                    dp[length + 1][new_bal][new_state] = (dp[length + 1][new_bal][new_state] + count) % MOD

                # Try adding ')'
                new_bal = balance - 1
                if new_bal >= 0:
                    # Update KMP state
                    if state < m:
                        if s[state] == ')':
                            new_state = state + 1
                        else:
                            k = state
                            while k > 0 and s[k] != ')':
                                k = pi[k - 1]
                            if s[k] == ')':
                                k += 1
                            new_state = k
                        if new_state == m:
                            new_state = m
                    else:
                        new_state = m

                    dp[length + 1][new_bal][new_state] = (dp[length + 1][new_bal][new_state] + count) % MOD

    # Sum all states where we have found the pattern (state == m) at length 2n
    ans = 0
    for balance in range(n + 1):
        ans = (ans + dp[2 * n][balance][m]) % MOD

    print(ans)

if __name__ == "__main__":
    solve()
